    public EngineTsf buildTransform(TaskDfDto taskDfDto) {

        Long taskId = taskDfDto.getId();
        String transformId = String.valueOf(taskId);

        // 处理转换节点
        EngineTsf transform = new EngineTsf();
        transform.setId(transformId);
        transform.setLabel(taskDfDto.getTaskName());
        // transform.setJobId(jobId);
        transform.setJobId(transformId);
        transform.setName(taskDfDto.getTaskName());

        // transform-> 处理step的连线
        List<EtlTaskStepHop> hops = taskDfDto.getHopList();
        for (EtlTaskStepHop hop : hops) {
            transform.addHop(String.valueOf(hop.getFromStepId()), String.valueOf(hop.getToStepId()));
        }

        // transform-> 处理step的节点
        List<TaskStepDto> stepList = taskDfDto.getStepList();
        Set<Long> datasourceIds = new HashSet<>();
        for (TaskStepDto stepDto : stepList) {

            StepData stepData = null;
            // 分节点类型处理
            switch (stepDto.getStepType()) {
                case TABLE_INPUT:
                    stepData = toTableInput(taskDfDto, stepDto);
                    break;
                case SQL_INPUT:
                    stepData = toSqlInput(taskDfDto, stepDto);
                    break;
                case TABLE_JOIN:
                    stepData = toTableJoin(taskDfDto, stepDto);
                    break;
                case TABLE_OUTPUT:
                    stepData = toTableOutput(taskDfDto, stepDto);
                    break;
                case EXECUTE_SCRIPT:
                    stepData = toExecuteScript(taskDfDto, stepDto);
                    break;
                case FLINK_REGISTER:
                    stepData = toFlinkRegister(taskDfDto, stepDto);
                    break;
                case FLINK_SCRIPT:
                case FLINK_SQL:
                    stepData = toFlinkScript(taskDfDto, stepDto);
                    break;
                case KAFKA_INPUTS:
                    stepData = toKafkaInput(taskDfDto, stepDto);
                    break;
                // case ENTERING_LAKE:
                // stepData = toEnteringLake(taskDfDto, stepDto);
                // datasourceIds.add(taskDfDto.getTargetDatasourceId());
                // break;
                case NLP_INPUT:
                    stepData = toNlpInput(taskDfDto, stepDto);
                    break;
                // case MOVING_INVENTORY:
                // stepData = toMovingInventory(taskDfDto, stepDto);
                // datasourceIds.add(taskDfDto.getTargetDatasourceId());
                // break;
                default:
                    log.error("Unknown step type: {}, step id: {}", stepDto.getStepType(), stepDto.getId());
                    break;
            }

            if (null == stepData) {
                continue;
            }
            transform.addStep(stepData);
            collectJdbcDatasourceId(stepDto, datasourceIds);
        }
        return transform;
    }

    public DfEngineParameters buildParameters(EtlScheduleJob scheduleJob, EtlScheduleTask scheduleTask,
                                              TaskDfDto taskDfDto, EtlJob etlJob) {

        String jobId = String.valueOf(etlJob.getId());
        DfEngineParameters parameters = new DfEngineParameters();
        parameters.setJobId(jobId);
