    /**
     * 转换为库表合并组件
     *
     * @param taskDfDto
     * @param stepDto
     * @return
     */
    private TableJoin toTableJoin(TaskDfDto taskDfDto, TaskStepDto stepDto) {

        if (!stepDto.isTableJoin()) {
            return null;
        }
        // 获取table_join 节点的join 条件
        Map<Long, List<EtlTaskStepJoin>> joinMap = stepDto.getJoins().stream()
                .sorted(Comparator.comparing(EtlTaskStepJoin::getOrderNo))
                .collect(Collectors.groupingBy(EtlTaskStepJoin::getJoinStepId, LinkedHashMap::new,
                        Collectors.toList()));

        // 获取所有的连线信息，
        // 获取进入join 节点的所有step 节点信息
        Map<Long, Set<Long>> hopMap = taskDfDto.getHopList().stream()
                .filter(hop -> Objects.nonNull(hop.getToStepId()))
                .collect(Collectors.groupingBy(EtlTaskStepHop::getToStepId,
                        Collectors.mapping(EtlTaskStepHop::getFromStepId, Collectors.toSet())));

        // 获取所有节点的具体信息
        Map<Long, TaskStepDto> stepDtoMap = taskDfDto.getStepList().stream()
                .collect(Collectors.toMap(TaskStepDto::getId, Function.identity()));

        // 处理join信息
        TableJoin tableJoin = new TableJoin();
        tableJoin.setId(String.valueOf(stepDto.getId()));
        tableJoin.setName(stepDto.getStepName());
        tableJoin.setTableName(stepDto.getTableName());

        // 遍历所有的join条件信息
        Map<String, TableRef> tableRefs = new HashMap<>();
        for (Long joinStepId : joinMap.keySet()) {

            TaskStepDto fromStep = stepDtoMap.get(joinStepId);
            if (null == fromStep /* || this.toBoolean(fromStep.getIsMain()) */) {
                continue;
            }

            // 右表处理
            TableRef rightTable = new TableRef();
            String rightTableAs = fromStep.getTableAlias();
            String tableName = fromStep.getTableName();
            rightTable.setTableCode(tableName);
            rightTable.setAsName(rightTableAs);
            rightTable.setMain(this.toBoolean(fromStep.getIsMain()));
            tableRefs.putIfAbsent(rightTable.getTableCode() + rightTable.getAsName(), rightTable);

            // 处理join的条件
            JoinOption joinOption = new JoinOption();
            joinOption.setRight(rightTable);

            // 遍历右表的各个条件
            List<EtlTaskStepJoin> joinList = joinMap.getOrDefault(joinStepId, new ArrayList<>());
            for (EtlTaskStepJoin stepJoin : joinList) {

                String conditionRelation = stepJoin.getConditionRelation();
                // 处理左节点-》左表
                Long leftStepId = stepJoin.getLeftStepId();
                TaskStepDto leftStep = stepDtoMap.getOrDefault(leftStepId, new TaskStepDto());

                String leftTableAs = leftStep.getTableAlias();
                String leftTableName = leftStep.getTableName();
                TableRef leftTable = new TableRef();
                leftTable.setTableCode(leftTableName);
                leftTable.setAsName(leftTableAs);
                leftTable.setMain(this.toBoolean(leftStep.getIsMain()));
                tableRefs.putIfAbsent(leftTable.getTableCode() + leftTable.getAsName(), leftTable);
                Map<String, EtlTaskColumn> leftColumnMap = leftStep.getColumns().stream().collect(
                        Collectors.toMap(EtlTaskColumn::getColumnName, Function.identity()));

                // todo 临时性提的 join_step_id
                if (joinOption.getRight().isMain()) {
                    joinOption.setRight(leftTable);
                }

                // 处理左表的列信息
                ColumnRef left = new ColumnRef();
                left.setTableCode(leftTableName);
                left.setTableAsName(leftTableAs);
                EtlTaskColumn leftColumn = leftColumnMap.get(stepJoin.getLeftColumnName());
                if (null != leftColumn) {
                    Column column = dfConverter.taskColumn2Column(leftColumn);
                    column.setTableAsName(StringUtils.isBlank(leftTableAs) ? leftTableName : leftTableAs);
                    left.setColumn(column);
                }

                JoinType joinType = stepJoin.getJoinType();

                if (CONDITION_TYPE_SQL.equals(stepJoin.getConditionType())) {
                    if (StringUtils.isEmpty(stepJoin.getConditionScript()) && !CROSS_JOIN.equals(joinType)) {
                        throw new WinningRuntimeException(
                                WinI18nUtils.loadString("库表合并[", "库表合并[") + joinType.getSql() + " " + tableName +
                                        WinI18nUtils.loadString("]关联条件为空，请检查关联条件！", "]关联条件为空，请检查关联条件！"));
                    }
                    joinOption.addCondition(stepJoin.getConditionScript());
                } else if (CONDITION_TYPE_DEF.equals(stepJoin.getConditionType())) {

                    // 处理右节点-》右表
                    Long rightStepId = stepJoin.getRightStepId();
                    TaskStepDto rightStep = stepDtoMap.get(rightStepId);

                    // 校验右节点
                    if (null == rightStep) {
                        throw new WinningRuntimeException(
                                WinI18nUtils.loadString("库表合并右表未维护请检查连接信息", "库表合并右表未维护，请检查join信息！"));
                    }

                    String rightTableName = rightStep.getTableName();
                    String rightTableAlias = rightStep.getTableAlias();
                    Map<String, EtlTaskColumn> rightColumnMap = rightStep.getColumns().stream()
                            .collect(Collectors.toMap(EtlTaskColumn::getColumnName, Function.identity()));
                    // 是def时，处理右表的信息
                    ColumnRef right = new ColumnRef();
                    right.setTableCode(rightTableName);
                    right.setTableAsName(rightTableAlias);
                    EtlTaskColumn rightColumn = rightColumnMap.get(stepJoin.getRightColumnName());
                    if (null != rightColumn) {
                        Column column = dfConverter.taskColumn2Column(rightColumn);
                        column.setTableAsName(
                                StringUtils.isBlank(rightTableAlias) ? rightTableName : rightTableAlias);
                        right.setColumn(column);
                    }

                    if ((null == rightColumn || null == leftColumn) && !CROSS_JOIN.equals(joinType)) {
                        throw new WinningRuntimeException(
                                WinI18nUtils.loadString("库表合并[", "库表合并[") + joinType.getSql() + " " + tableName +
                                        WinI18nUtils.loadString("]关联关系异常，请检查关联关系！", "]关联关系异常，请检查关联关系！"));
                    }

                    joinOption.addCondition(left, conditionRelation, right);
                }
                joinOption.setJoinType(joinType);
            }
            tableJoin.addJoin(joinOption);
        }

        // 处理未在join列表的前置节点
        for (Long stepId : hopMap.get(stepDto.getId())) {
            TaskStepDto taskStepDto = stepDtoMap.get(stepId);
            if (null == taskStepDto) {
                continue;
            }
            TableRef tableRef = new TableRef();
            tableRef.setTableCode(taskStepDto.getTableName());
            tableRef.setAsName(taskStepDto.getTableAlias());
            tableRef.setMain(this.toBoolean(taskStepDto.getIsMain()));
            tableRefs.putIfAbsent(tableRef.getTableCode() + tableRef.getAsName(), tableRef);
        }
        tableRefs.values().forEach(tableJoin::addTable);
        return tableJoin;
    }

