        DfJobRun jobRun = new DfJobRun();
        jobRun.setJobId(taskDfDto.getJobId());
        jobRun.setTaskId(taskDfDto.getId());
        jobRun.setOrgId(taskDfDto.getOrgId());
        parameters.setJobRun(jobRun);

        return parameters;
    }

