    public DfEngineParameters buildBigDataParameters(EtlScheduleJob scheduleJob, EtlScheduleTask scheduleTask,
                                                     List<TaskDetail> taskDetails, JobDetail jobDetail,
                                                     IntegrationReadContext readContext) {

        int etlType = jobDetail.getEtlType();
        String jobId = String.valueOf(jobDetail.getId());
        DfEngineParameters parameters = new DfEngineParameters();
        parameters.setJobId(jobId);
        parameters.setOrgId(scheduleJob.getOrgId());
        // 启动模式
        parameters.setStartMode(scheduleJob.getStartMode());

        String orgName = frameService.getSysOrgName(scheduleJob.getOrgId());
        parameters.setName(AdapterUtil.getProcessDefinitionName(jobDetail, orgName));
        parameters.setMode(scheduleJob.getExecutionMode());
        parameters.setEngineAddress("");
        parameters.setFlinkAddress("");
        parameters.setClusterId(scheduleJob.getWorkCluster());
        if (null != scheduleTask && null != scheduleTask.getWorkCluster()) {
            parameters.setClusterId(scheduleTask.getWorkCluster());
        }

        // 根据不同情况来决定，如果是调试，或者是实时的，多个task合成一个taskDefinition
        // 则transformId = jobId，否则，transformId = taskId
        String transformId = jobId;
        if (null != scheduleTask) {
            transformId = String.valueOf(scheduleTask.getTaskId());
            parameters.setEtlTaskId(transformId);
        }

        // 处理转换节点
        EngineTsf transform = new EngineTsf();
        transform.setId(transformId);
        transform.setLabel(jobDetail.getJobName());
        // transform.setJobId(jobId);
        transform.setJobId(transformId);
        transform.setName(jobDetail.getJobName());

        // transform-> 处理step的节点
        // 需要从taskDetails和job中获取并组装
        Set<Long> datasourceIds = new HashSet<>();

        StepData stepData = null;

        // 分节点类型处理
        switch (etlType) {

            case 1:
                stepData = TransToEnteringLake(jobDetail, taskDetails, readContext);
                break;
            case 2:
                stepData = TransToMovingInventory(jobDetail, taskDetails, readContext);
                break;
            default:
                log.error("非一键入湖或整库同步组件类型，etlType: {}", etlType);
                break;
        }

        if (null != stepData) {
            transform.addStep(stepData);
        }

        datasourceIds.add(jobDetail.getSourceDatasourceId());
        datasourceIds.add(jobDetail.getTargetDatasourceId());

        // transform的 start 和 end节点
        Start start = newStart(transformId);
        End end = newEnd(transformId);

        // job添加节点
        parameters.addStep(start);
        parameters.addStep(transform);
        parameters.addStep(end);

        // job处理连线
        parameters.addHop(start.getId(), transformId);
        parameters.addHop(transformId, end.getId());

        // 数据源
        for (Long datasourceId : datasourceIds) {
            Connection connection = new Connection();
            connection.setId(datasourceId);
            parameters.addConnection(connection);
        }

        // 时间管理表
        DfJobRun jobRun = new DfJobRun();
        jobRun.setJobId(jobDetail.getId());

        if (null == scheduleTask) {
            jobRun.setTaskId(jobDetail.getId());
        } else {
            jobRun.setTaskId(scheduleTask.getTaskId());
        }

        jobRun.setOrgId(jobDetail.getOrgId());
        parameters.setJobRun(jobRun);

        return parameters;
    }

