    /**
     * 转换为表输出
     *
     * @param taskDfDto
     * @param stepDto
     * @return
     */
    private TableOutput toTableOutput(TaskDfDto taskDfDto, TaskStepDto stepDto) {

        if (!stepDto.isTableOutput()) {
            return null;
        }

        String tableName = stepDto.getTableName();
        String tableAlias = stepDto.getTableAlias();

        // 处理基础信息
        TableOutput tableOutput = new TableOutput();
        tableOutput.setId(String.valueOf(stepDto.getId()));
        tableOutput.setName(stepDto.getStepName());
        tableOutput.setTableCode(tableName);
        tableOutput.setSchema(stepDto.getSchemaName());
        tableOutput.setTableName(tableName);
        tableOutput.setDbId(String.valueOf(stepDto.getDatasourceId()));
        tableOutput.setTableAsName(tableAlias);
        tableOutput.setAsName(tableAlias);
        tableOutput.setEventTimeColumn(stepDto.getEventTime());
        tableOutput.setDictColumn(stepDto.getDictColumn());
        // 增加操作类型
        if (Objects.nonNull(stepDto.getOperateType())) {
            tableOutput.setOperateType(stepDto.getOperateType().name());
        }
        // 处理目标表的列信息
        List<Column> columnList = dfConverter.taskColumn2Column(sortColumnsByPosition(stepDto.getColumns()));
        for (Column column : columnList) {
            column.setTableAsName(StringUtils.isBlank(tableAlias) ? tableName : tableAlias);
        }

        // 处理所有节点的列别名信息（Kafka 等组件列在 relatedTables，不在 step.columns）
        Set<EtlTaskColumn> columns = collectUpstreamColumnsForMapping(taskDfDto);

        // 转换数据 处理mapping信息
        Function<EtlTaskColumn, String> sourceFunc = column -> column.getTableAlias() + "." + column.getColumnName();
        Function<EtlTaskColumn, String> targetFunc = EtlTaskColumn::getColumnName;
        Map<String, EtlTaskColumn> tableAliasColumnMap = columns.stream().collect(
                Collectors.toMap(column -> sourceFunc.apply(column), Function.identity()));
        Map<String, EtlTaskColumn> targetColumns = stepDto.getColumns().stream().collect(
                Collectors.toMap(column -> targetFunc.apply(column), Function.identity()));

        Map<Long, TaskStepDto> stepMap = taskDfDto.getStepList().stream().collect(
                Collectors.toMap(TaskStepDto::getId, Function.identity()));
        List<TaskMappingDto> mappings = stepDto.getMappings();
        if (CollectionUtils.isEmpty(mappings)) {
            throw new WinningRuntimeException(WinI18nUtils.loadString("库表输出节点映射信息不能为空", "库表输出节点映射信息不能为空"));
        }
        for (TaskMappingDto mapping : mappings) {

            ColPair colPair = new ColPair();
            ColFunc source = new ColFunc();
            Column target = new Column();
            colPair.setSource(source);
            colPair.setTarget(target);

            String targetColumnName = mapping.getTargetColumnName();
            Integer isPrimarykey = mapping.getIsPrimarykey();
            String sourceColumnName = mapping.getSourceColumnName();
            String sourceColumnAlias = mapping.getSourceColumnAlias();
            String sourceColumnType = mapping.getSourceColumnType();
            Long sourceStepId = mapping.getSourceStepId();
            Integer lockType = mapping.getLockType();
            Integer isCheck = mapping.getIsCheck();

            // 移除映射中未选中的column; 如果mapping字段和column 没有对应上，引擎会报错
            if (null != isCheck && isCheck == 0) {
                columnList.removeIf(p -> p.getColumnName().equals(targetColumnName));
                continue;
            }

            // 处理源端
            ColFuncType sourceType = mapping.getSourceType();
            source.setType(sourceType);
            source.setAsName(sourceColumnAlias);
            source.setColumnName(sourceColumnName);
            source.setColumnType(sourceColumnType);
            // 是否锁定类型的标志
            source.setLockType(this.toBoolean(lockType));
            if (ColFuncType.FIELD.equals(sourceType)) {

                String tableAs = "";
                TaskStepDto sourceStep = stepMap.get(sourceStepId);
                if (null == sourceStep) {
                    continue;
                }

                tableAs = resolveSourceStepTableAlias(sourceStep);
                // EtlTaskColumn sourceColumn = tableAliasColumnMap.get(tableAs + "." + sourceColumnName);
                EtlTaskColumn sourceColumn = this.searchColumn(tableAs + "." + sourceColumnName,
                        tableAliasColumnMap, sourceFunc);

                if (null == sourceColumn) {
                    // todo
                    continue;
                }
                source.setPk(this.toBoolean(sourceColumn.getIsPrimarykey()));
                source.setNotNull(this.toBoolean(sourceColumn.getNotNull()));
                source.setTableAsName(sourceColumn.getTableAlias());
                // 锁定类型，从mapping 中获取
                if (Const.YES.equals(lockType)) {
                    source.setColumnType(mapping.getSourceColumnType());
                    source.setColumnSize(mapping.getSourceColumnPrecision());
                    source.setColumnAccuracy(mapping.getSourceColumnScale());
                } else {
                    source.setColumnType(sourceColumn.getColumnType());
                    source.setColumnSize(sourceColumn.getColumnPrecision());
                    source.setColumnAccuracy(sourceColumn.getColumnScale());
                }
                if (!sourceColumnName.contains(".")) {
                    source.setColumnName(tableAs + "." + sourceColumnName);
                }
            }

            // 处理多机构场景下的valueMapping函数：拼装当前机构的org_id信息
            source.setColumnName(
                    this.processValueMappingOrgId(source.getColumnName(), taskDfDto.getOrgId()));

            // 处理目标
            // EtlTaskColumn targetColumn = targetColumns.get(targetColumnName);
            EtlTaskColumn targetColumn = this.searchColumn(targetColumnName, targetColumns, targetFunc);

            if (null == targetColumn) {
                // todo
                String msg = String.format(
                        WinI18nUtils.loadString("输出节点目标字段为空或关联失败", "%s的输出节点[%s]的目标字段[%s]为空或者关联失败!"),
                        taskDfDto.getTaskName(), stepDto.getTableName(), targetColumnName);
                throw new WinningRuntimeException(msg);
            } else {
                target.setAsName(targetColumn.getColumnName());
                target.setColumnName(targetColumn.getColumnName());
                target.setColumnType(targetColumn.getColumnType());
                target.setPk(this.toBoolean(isPrimarykey));
                target.setColumnType(targetColumn.getColumnType());
                target.setAsName(targetColumn.getColumnAlias());
                target.setNotNull(this.toBoolean(targetColumn.getNotNull()));
                target.setColumnSize(targetColumn.getColumnPrecision());
                target.setColumnAccuracy(targetColumn.getColumnScale());
                target.setTableAsName(targetColumn.getTableAlias());
            }

            tableOutput.addMapping(colPair);
        }
        tableOutput.setColumns(columnList);
        return tableOutput;
    }"}}
